import db from "./work.json";

/* work.json is generated by scripts/sync-work.mjs from the work folders.
   Per-item fields you can edit by hand: "title", "client", "featured": true, "hidden": true */

const HIDE_CLIENT = /daxator/i; // keep this portfolio anonymous

export const WORK = db.items
  .filter((i) => !i.hidden)
  .map((i) => ({ ...i, client: HIDE_CLIENT.test(i.client || "") ? "" : i.client || "" }));

export const CATEGORIES = [
  { slug: "all", name: "All" },
  ...db.categories.filter((c) => WORK.some((i) => i.category === c.slug)),
];

export const byCategory = (slug) => (slug === "all" ? WORK : WORK.filter((i) => i.category === slug));
export const countOf = (slug) => byCategory(slug).length;
export const catName = (slug) => CATEGORIES.find((c) => c.slug === slug)?.name || slug;

const wideish = (i) => i.orientation !== "portrait";

/* What plays on the big screen in the header for each category */
export function stageFor(slug) {
  if (slug === "fooh") return { mode: "phones", items: byCategory("fooh").filter((i) => i.type === "video") };
  if (slug === "all") {
    const ana = WORK.filter((i) => i.category === "anamorphic" && i.type === "video" && i.orientation === "landscape");
    const feat = ana.filter((i) => i.featured);
    const rest = ana.filter((i) => !i.featured);
    const others = WORK.filter((i) => i.featured && i.category !== "anamorphic" && i.type === "video" && wideish(i));
    return { mode: "screen", items: [...feat, ...rest.slice(0, 3), ...others] };
  }
  const all = byCategory(slug);
  const wide = all.filter(wideish);
  return { mode: "screen", items: wide.length >= 2 ? wide : all };
}

export const fmtDuration = (s) => (s ? `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, "0")}` : "");
